const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const response = await fetch(`${runnerBase}/jobs`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ action: 'ui_consistency_report', mode: 'sync', args: [] }),
});
const raw = await response.text();
if (!response.ok) throw new Error(`ui_consistency_report failed: ${response.status} ${raw}`);
const result = raw ? JSON.parse(raw) : {};
const output = result.stdout ? JSON.parse(result.stdout) : {};
return [{ json: { result, output } }];
